def js_array(lst): return json.dumps(lst)

# Category bar chart data (top 8 by product count)
cat8 = cat_stats[:8]
cat_labels = js_array([c['top_category'] for c in cat8])
cat_counts = js_array([c['product_count'] for c in cat8])
cat_ratings = js_array([round(c['avg_rating'],2) for c in cat8])
cat_discounts = js_array([round(c['avg_discount'],1) for c in cat8])

# Rating distribution
rd_labels = js_array(rating_dist['labels'])
rd_values = js_array(rating_dist['values'])

# Price segment
ps_labels = js_array([p['price_segment'] for p in price_seg])
ps_ratings = js_array([round(p['avg_rating'],2) for p in price_seg])
ps_discounts = js_array([round(p['avg_discount'],1) for p in price_seg])
ps_counts = js_array([p['count'] for p in price_seg])

# Discount bucket
db_labels = js_array([d2['disc_bucket'] for d2 in disc_stats])
db_ratings = js_array([round(d2['avg_rating'],2) for d2 in disc_stats])
db_counts_arr = js_array([d2['count'] for d2 in disc_stats])
db_eng = js_array([round(d2['avg_rating_count'],0) for d2 in disc_stats])

# Sentiment bar chart
pos_labels = js_array([p[0].title() for p in pos_themes])
pos_vals = js_array([p[1] for p in pos_themes])
neg_labels = js_array([n[0].title() for n in neg_themes])
