# Top/bottom category table rows
def cat_rows(lst, color):
    rows = ''
    for i, c in enumerate(lst):
        rows += f"""
        <tr>
          <td class="rank-cell {color}">{i+1}</td>
          <td><strong>{c['top_category']}</strong></td>
          <td class="num">{c['product_count']}</td>
          <td class="num rating-val">{c['avg_rating']:.2f}</td>
          <td class="num">{c['avg_discount']:.1f}%</td>
        </tr>"""
    return rows

top_rows = cat_rows(top5, 'top')
bot_rows = cat_rows(list(reversed(bottom5)), 'bot')

# Engagement table
eng_rows = ''
for i, p in enumerate(top_engaged[:10]):
