#!/usr/bin/env python3
"""Generate the final HTML analytics report."""
import json

with open('/app/output/analysis_data.json') as f:
    d = json.load(f)

kpis = d['kpis']
cat_stats = d['cat_stats']
top5 = d['top5_rating']
bottom5 = d['bottom5_rating']
rating_dist = d['rating_dist']
price_seg = d['price_seg']
disc_stats = d['disc_stats']
top_engaged = d['top_engaged']
pos_themes = d['pos_themes']
neg_themes = d['neg_themes']
subcat = d['subcat_stats']

# ── Chart data helpers ────────────────────────────────────────────────────────
def js_array(lst): return json.dumps(lst)

# Category bar chart data (top 8 by product count)
cat8 = cat_stats[:8]
cat_labels = js_array([c['top_category'] for c in cat8])
cat_counts = js_array([c['product_count'] for c in cat8])
cat_ratings = js_array([round(c['avg_rating'],2) for c in cat8])
cat_discounts = js_array([round(c['avg_discount'],1) for c in cat8])

# Rating distribution
rd_labels = js_array(rating_dist['labels'])
rd_values = js_array(rating_dist['values'])

# Price segment
ps_labels = js_array([p['price_segment'] for p in price_seg])
ps_ratings = js_array([round(p['avg_rating'],2) for p in price_seg])
ps_discounts = js_array([round(p['avg_discount'],1) for p in price_seg])
ps_counts = js_array([p['count'] for p in price_seg])

# Discount bucket
db_labels = js_array([d2['disc_bucket'] for d2 in disc_stats])
db_ratings = js_array([round(d2['avg_rating'],2) for d2 in disc_stats])
db_counts_arr = js_array([d2['count'] for d2 in disc_stats])
db_eng = js_array([round(d2['avg_rating_count'],0) for d2 in disc_stats])

# Sentiment bar chart
pos_labels = js_array([p[0].title() for p in pos_themes])
pos_vals = js_array([p[1] for p in pos_themes])
neg_labels = js_array([n[0].title() for n in neg_themes])
neg_vals = js_array([n[1] for n in neg_themes])

# Top/bottom category table rows
def cat_rows(lst, color):
    rows = ''
    for i, c in enumerate(lst):
        rows += f"""
        <tr>
          <td class="rank-cell {color}">{i+1}</td>
          <td><strong>{c['top_category']}</strong></td>
          <td class="num">{c['product_count']}</td>
          <td class="num rating-val">{c['avg_rating']:.2f}</td>
          <td class="num">{c['avg_discount']:.1f}%</td>
        </tr>"""
    return rows

top_rows = cat_rows(top5, 'top')
bot_rows = cat_rows(list(reversed(bottom5)), 'bot')

# Engagement table
eng_rows = ''
for i, p in enumerate(top_engaged[:10]):
    eng_rows += f"""
    <tr>
      <td class="rank-cell top">{i+1}</td>
      <td class="product-name">{p['product_name']}</td>
      <td>{p['top_category']}</td>
      <td class="num rating-val">{p['rating']}</td>
      <td class="num"><strong>{p['rating_count']}</strong></td>
      <td class="num">{p['discount_percentage']:.0f}%</td>
    </tr>"""

# Sub-category table
subcat_rows = ''
for s in subcat[:10]:
    subcat_rows += f"""
    <tr>
      <td>{s['sub_category']}</td>
      <td class="num">{s['product_count']}</td>
      <td class="num rating-val">{s['avg_rating']:.2f}</td>
      <td class="num">{s['avg_discount']:.1f}%</td>
    </tr>"""

corr_val = kpis['disc_rating_corr']
corr_label = "Weak negative" if corr_val < -0.1 else ("Weak positive" if corr_val > 0.1 else "Near zero")
corr_color = "#e74c3c" if corr_val < 0 else "#27ae60"

