    margin-top: 28px;
    display: flex;
    gap: 32px;
    flex-wrap: wrap;
  }}
  .report-header .meta-item {{ font-size: 12px; opacity: .8; }}
  .report-header .meta-item strong {{ display: block; font-size: 20px; font-weight: 700; opacity: 1; margin-bottom: 2px; }}

  /* ── Layout ── */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 32px 40px; }}
  .section {{ margin-bottom: 48px; }}
  .section-title {{
    font-size: 18px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 6px;
    padding-bottom: 10px;
    border-bottom: 2px solid var(--accent);
    display: flex;
    align-items: center;
    gap: 10px;
  }}
  .section-icon {{ font-size: 20px; }}
  .section-sub {{ color: var(--muted); font-size: 12px; margin-bottom: 20px; margin-top: 2px; }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
  }}
  .kpi-card {{
    background: var(--card);
    border-radius: 10px;
    padding: 20px 22px;
    border: 1px solid var(--border);
    box-shadow: 0 1px 4px rgba(0,0,0,.05);
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--accent2);
  }}
  .kpi-card.accent::before {{ background: var(--accent); }}
  .kpi-card.success::before {{ background: var(--success); }}
  .kpi-card.warn::before {{ background: var(--warn); }}
  .kpi-label {{ font-size: 11px; text-transform: uppercase; letter-spacing: .6px; color: var(--muted); margin-bottom: 8px; }}
  .kpi-value {{ font-size: 32px; font-weight: 700; color: var(--primary); line-height: 1; }}
  .kpi-unit {{ font-size: 14px; font-weight: 400; color: var(--muted); margin-left: 2px; }}
  .kpi-note {{ font-size: 11px; color: var(--muted); margin-top: 6px; }}

  /* ── Charts ── */
  .chart-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
  }}
  .chart-grid.thirds {{ grid-template-columns: 1fr 1fr 1fr; }}
  @media (max-width: 800px) {{
    .chart-grid, .chart-grid.thirds {{ grid-template-columns: 1fr; }}
  }}
  .chart-card {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px;
    box-shadow: 0 1px 4px rgba(0,0,0,.05);
  }}
  .chart-card.wide {{ grid-column: 1 / -1; }}
  .chart-title {{ font-size: 13px; font-weight: 600; color: var(--primary); margin-bottom: 4px; }}
  .chart-desc {{ font-size: 11px; color: var(--muted); margin-bottom: 16px; }}
  .chart-wrap {{ position: relative; height: 260px; }}
  .chart-wrap.tall {{ height: 320px; }}

  /* ── Tables ── */
  .table-wrap {{ overflow-x: auto; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  th {{ background: var(--primary); color: #fff; padding: 10px 12px; text-align: left; font-weight: 600; font-size: 11px; letter-spacing: .4px; text-transform: uppercase; }}
  td {{ padding: 9px 12px; border-bottom: 1px solid var(--border); }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover td {{ background: #f8f9fc; }}
  .num {{ text-align: right; font-variant-numeric: tabular-nums; }}
  .rating-val {{ color: var(--primary); font-weight: 600; }}
  .rank-cell {{
    width: 36px;
    text-align: center;
    font-weight: 700;
    border-radius: 50%;
    font-size: 12px;
  }}
  .rank-cell.top {{ color: var(--success); }}
  .rank-cell.bot {{ color: var(--danger); }}
  .product-name {{ max-width: 400px; color: var(--text); }}

  /* ── Insight boxes ── */
  .insight-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 20px;
  }}
  .insight-box {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
    border-left: 4px solid var(--accent2);
  }}
  .insight-box.warn {{ border-left-color: var(--warn); }}
  .insight-box.success {{ border-left-color: var(--success); }}
  .insight-box.danger {{ border-left-color: var(--danger); }}
  .insight-label {{ font-size: 11px; text-transform: uppercase; letter-spacing: .5px; color: var(--muted); margin-bottom: 6px; }}
  .insight-val {{ font-size: 26px; font-weight: 700; color: var(--primary); }}
  .insight-note {{ font-size: 12px; color: var(--muted); margin-top: 4px; }}

  /* ── Corr indicator ── */
  .corr-block {{
    display: flex;
    align-items: center;
    gap: 24px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 24px;
    margin-bottom: 20px;
  }}
  .corr-circle {{
    width: 80px; height: 80px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: 700;
    color: #fff;
    flex-shrink: 0;
    background: {corr_color};
  }}
  .corr-circle span {{ font-size: 10px; font-weight: 400; opacity: .9; }}
  .corr-text h3 {{ font-size: 15px; font-weight: 600; margin-bottom: 6px; }}
  .corr-text p {{ font-size: 13px; color: var(--muted); line-height: 1.5; }}

  /* ── Sentiment ── */
  .sentiment-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }}
  .sentiment-card {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }}
  .sentiment-card h4 {{ font-size: 13px; font-weight: 600; margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }}
  .sent-dot {{ width: 10px; height: 10px; border-radius: 50%; }}
  .positive .sent-dot {{ background: var(--success); }}
  .negative .sent-dot {{ background: var(--danger); }}

  /* ── Recommendations ── */
  .rec-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }}
  .rec-card {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px;
    border-top: 3px solid var(--accent);
  }}
  .rec-card:nth-child(2) {{ border-top-color: var(--accent2); }}
  .rec-card:nth-child(3) {{ border-top-color: var(--success); }}
  .rec-card:nth-child(4) {{ border-top-color: var(--warn); }}
  .rec-card:nth-child(5) {{ border-top-color: #9b59b6; }}
  .rec-num {{ font-size: 28px; font-weight: 800; color: #e0e4eb; margin-bottom: 8px; }}
  .rec-title {{ font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 8px; }}
  .rec-body {{ font-size: 13px; color: var(--muted); line-height: 1.6; }}
  .rec-stat {{ display: inline-block; background: #f0f4ff; color: var(--accent2); font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 4px; margin-top: 8px; }}

  /* ── Footer ── */
  .report-footer {{
    background: var(--primary);
    color: rgba(255,255,255,.6);
    text-align: center;
    padding: 20px;
    font-size: 11px;
    margin-top: 40px;
  }}

  /* ── Misc ── */
  .two-col-table {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  @media (max-width: 700px) {{
    .two-col-table, .insight-row, .rec-grid, .sentiment-grid {{ grid-template-columns: 1fr; }}
    .container {{ padding: 20px; }}
  }}
</style>
</head>
<body>

<!-- ═══ HEADER ═══════════════════════════════════════════════════════════════ -->
<div class="report-header">
  <div class="badge">Analytics Report · Management Edition</div>
  <h1>Amazon Product Catalog Performance &amp; Customer Sentiment Analysis</h1>
  <p class="subtitle">Pricing strategy, discount effectiveness, category performance, and customer engagement across 1,465 Amazon India products</p>
  <div class="meta">
    <div class="meta-item"><strong>{kpis['total_products']:,}</strong>Products Analyzed</div>
    <div class="meta-item"><strong>{kpis['avg_rating']}</strong>Avg. Rating (1–5)</div>
    <div class="meta-item"><strong>{kpis['avg_discount']}%</strong>Avg. Discount</div>
    <div class="meta-item"><strong>{kpis['high_rating_share']}%</strong>Rated 4.0+</div>
    <div class="meta-item"><strong>Amazon India</strong>Marketplace</div>
    <div class="meta-item"><strong>April 2026</strong>Report Date</div>
  </div>
</div>

<div class="container">

<!-- ═══ SECTION 1: EXECUTIVE OVERVIEW ═══════════════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">📊</span> Executive Overview</h2>
  <p class="section-sub">Headline KPIs across the full 1,465-product catalog · Amazon India snapshot</p>

  <div class="kpi-grid">
    <div class="kpi-card accent">
      <div class="kpi-label">Total Products</div>
      <div class="kpi-value">{kpis['total_products']:,}</div>
      <div class="kpi-note">Across 3 primary categories</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Average Customer Rating</div>
      <div class="kpi-value">{kpis['avg_rating']}<span class="kpi-unit">/ 5</span></div>
      <div class="kpi-note">Mean across rated products</div>
    </div>
    <div class="kpi-card success">
      <div class="kpi-label">High-Rating Share (≥4.0)</div>
      <div class="kpi-value">{kpis['high_rating_share']}<span class="kpi-unit">%</span></div>
      <div class="kpi-note">Strong catalog quality signal</div>
    </div>
    <div class="kpi-card warn">
      <div class="kpi-label">Average Discount</div>
      <div class="kpi-value">{kpis['avg_discount']}<span class="kpi-unit">%</span></div>
      <div class="kpi-note">Heavy promotional intensity</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Median Rating Count</div>
      <div class="kpi-value">{kpis['median_rating_count']:,}</div>
      <div class="kpi-note">Typical product engagement</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Discount–Rating Correlation</div>
      <div class="kpi-value">{kpis['disc_rating_corr']}</div>
      <div class="kpi-note">Discounts ≠ higher satisfaction</div>
    </div>
  </div>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Rating Distribution</div>
      <div class="chart-desc">Share of products by rating band — catalog skews strongly toward 4–4.5★</div>
      <div class="chart-wrap"><canvas id="ratingDistChart"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Category Mix by Product Count</div>
      <div class="chart-desc">Electronics, Computers & Accessories, and Home & Kitchen dominate the catalog</div>
      <div class="chart-wrap"><canvas id="catMixChart"></canvas></div>
    </div>
  </div>
</div>

<!-- ═══ SECTION 2: CATEGORY PERFORMANCE ══════════════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">🏷️</span> Category Performance Breakdown</h2>
  <p class="section-sub">Average rating, discount intensity, and engagement by top-level category · minimum 10 products per category</p>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Average Rating by Category</div>
      <div class="chart-desc">Office Products leads with 4.31★; Home &amp; Kitchen trails at 4.04★</div>
      <div class="chart-wrap"><canvas id="catRatingChart"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Average Discount % by Category</div>
      <div class="chart-desc">Computers &amp; Accessories carries the deepest promotions at 54% average</div>
      <div class="chart-wrap"><canvas id="catDiscChart"></canvas></div>
    </div>
  </div>

  <div class="two-col-table" style="margin-bottom:20px;">
    <div>
      <div class="chart-card">
        <div class="chart-title" style="color:var(--success);margin-bottom:12px;">🏆 Top 5 Categories by Rating</div>
        <div class="table-wrap">
          <table>
            <thead><tr><th>#</th><th>Category</th><th>Products</th><th>Avg Rating</th><th>Avg Disc.</th></tr></thead>
            <tbody>{top_rows}</tbody>
          </table>
        </div>
      </div>
    </div>
    <div>
      <div class="chart-card">
        <div class="chart-title" style="color:var(--danger);margin-bottom:12px;">⚠️ Bottom Categories by Rating</div>
        <div class="table-wrap">
          <table>
            <thead><tr><th>#</th><th>Category</th><th>Products</th><th>Avg Rating</th><th>Avg Disc.</th></tr></thead>
            <tbody>{bot_rows}</tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

  <div class="chart-card">
    <div class="chart-title">Top 10 Sub-Categories by Product Count</div>
    <div class="chart-desc">Second-level category breakdown — USB Cables and Smartphones represent the largest sub-segments</div>
    <div class="chart-wrap tall"><canvas id="subcatChart"></canvas></div>
  </div>
</div>

<!-- ═══ SECTION 3: PRICING & DISCOUNT STRATEGY ═══════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">💰</span> Pricing &amp; Discount Strategy Analysis</h2>
  <p class="section-sub">Does discounting drive satisfaction? Examining discount depth vs. rating and review volume</p>

  <div class="corr-block">
    <div class="corr-circle">
      {kpis['disc_rating_corr']}<span>r value</span>
    </div>
    <div class="corr-text">
      <h3>Discount–Rating Correlation: <span style="color:{corr_color}">{corr_label}</span> ({kpis['disc_rating_corr']})</h3>
      <p>Deeper discounts show a <strong>weak negative correlation</strong> with customer ratings (r = {kpis['disc_rating_corr']}). Products with the heaviest discounts (80–100%) average <strong>4.02★</strong>, while lightly discounted products (0–10%) average <strong>4.21★</strong> — a 0.19-point gap. This suggests heavy discounting does <em>not</em> lift customer satisfaction and may reflect lower-quality products being cleared through promotions.</p>
      <p style="margin-top:6px;">Discount–Review Volume correlation: <strong>{kpis['disc_count_corr']}</strong> (near zero) — discounting does not materially drive review volume either.</p>
    </div>
  </div>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Avg. Rating by Discount Bracket</div>
      <div class="chart-desc">Ratings gradually decline as discount depth increases — highest-discount tier (80–100%) shows the lowest average rating</div>
      <div class="chart-wrap"><canvas id="discRatingChart"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Product Count by Discount Bracket</div>
      <div class="chart-desc">Most products cluster in the 40–70% discount range, indicating aggressive promotional defaults</div>
      <div class="chart-wrap"><canvas id="discCountChart"></canvas></div>
    </div>
  </div>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Avg. Rating by Price Segment</div>
      <div class="chart-desc">Premium products (₹5K+) earn the highest ratings (4.17★) with the smallest discounts (33.5%) — value-quality alignment</div>
      <div class="chart-wrap"><canvas id="priceSegRatingChart"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Avg. Discount % by Price Segment</div>
      <div class="chart-desc">Entry-level products (&lt;₹200) carry nearly 58% average discounts — the heaviest promotional burden</div>
      <div class="chart-wrap"><canvas id="priceSegDiscChart"></canvas></div>
    </div>
  </div>

  <div class="insight-row">
    <div class="insight-box success">
      <div class="insight-label">Premium Segment (₹5K+)</div>
      <div class="insight-val">4.17★</div>
      <div class="insight-note">Highest avg. rating with only 33.5% avg. discount — best quality-value balance</div>
    </div>
    <div class="insight-box danger">
      <div class="insight-label">Heavy Discount Tier (80–100%)</div>
      <div class="insight-val">4.02★</div>
      <div class="insight-note">Lowest avg. rating in any discount bracket — discounting is not compensating for lower quality</div>
    </div>
  </div>
</div>

<!-- ═══ SECTION 4: CUSTOMER ENGAGEMENT ═══════════════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">🌟</span> Customer Engagement &amp; Rating Distribution</h2>
  <p class="section-sub">Rating volume, engagement outliers, and product-level engagement benchmarks</p>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Avg. Review Count by Discount Bracket</div>
      <div class="chart-desc">60–70% discount bracket shows the highest average engagement (26,431 reviews) — driven by high-volume Electronics SKUs</div>
      <div class="chart-wrap"><canvas id="discEngChart"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Product Count by Price Segment</div>
      <div class="chart-desc">The ₹200–500 segment is the most densely populated (377 products), followed closely by ₹1K–2K</div>
      <div class="chart-wrap"><canvas id="priceCountChart"></canvas></div>
    </div>
  </div>

  <div class="chart-card" style="margin-bottom:20px;">
    <div class="chart-title">Top 10 Most-Reviewed Products</div>
    <div class="chart-desc">Amazon Basics HDMI and boAt earphones dominate engagement — all are Electronics, all rated 4.1–4.4★</div>
    <div class="table-wrap">
      <table>
        <thead><tr><th>#</th><th>Product</th><th>Category</th><th>Rating</th><th>Review Count</th><th>Discount</th></tr></thead>
        <tbody>{eng_rows}</tbody>
      </table>
    </div>
  </div>

  <div class="insight-row">
    <div class="insight-box">
      <div class="insight-label">Median Review Count</div>
      <div class="insight-val">{kpis['median_rating_count']:,}</div>
      <div class="insight-note">Typical product engagement benchmark — the top 10 are 85× above this median</div>
    </div>
    <div class="insight-box warn">
      <div class="insight-label">Top Product Review Count</div>
      <div class="insight-val">426,973</div>
      <div class="insight-note">Amazon Basics HDMI Cable — engagement driven by trusted brand + near-commodity product</div>
    </div>
  </div>
</div>

<!-- ═══ SECTION 5: REVIEW SENTIMENT SNAPSHOT ════════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">💬</span> Review Sentiment Snapshot</h2>
  <p class="section-sub">High-level qualitative themes extracted from {kpis['total_products']:,} product review titles</p>

  <div class="sentiment-grid">
    <div class="sentiment-card positive">
      <h4><span class="sent-dot"></span>Most Common Positive Themes</h4>
      <div class="chart-wrap" style="height:220px;"><canvas id="posChart"></canvas></div>
    </div>
    <div class="sentiment-card negative">
      <h4><span class="sent-dot"></span>Most Common Negative Themes</h4>
      <div class="chart-wrap" style="height:220px;"><canvas id="negChart"></canvas></div>
    </div>
  </div>

  <div style="margin-top:16px; background:var(--card); border:1px solid var(--border); border-radius:10px; padding:20px 24px;">
    <h4 style="font-size:13px;font-weight:600;margin-bottom:10px;">Sentiment Interpretation</h4>
    <p style="font-size:13px;color:var(--muted);line-height:1.7;">
      <strong style="color:var(--success)">Positive signals</strong> — "Good" (3,936 mentions), "Quality" (761), and "Value" (489) are the dominant positive themes, indicating customers primarily judge products on basic functionality and value-for-money rather than premium features. "Fast" (charging/delivery) is also prominent, aligning with the catalog's heavy cable/charger mix.
    </p>
    <p style="font-size:13px;color:var(--muted);line-height:1.7;margin-top:8px;">
      <strong style="color:var(--danger)">Negative signals</strong> — Negative vocabulary is proportionally small (total ~400 mentions vs. 6,000+ positive), but "Bad" (117), "Issue" (76), and "Poor" (46) indicate a minority of products generating quality and reliability complaints. "Defective" and "Damage" point to fulfillment or quality-control gaps in specific SKUs.
    </p>
  </div>
</div>

<!-- ═══ SECTION 6: STRATEGIC RECOMMENDATIONS ════════════════════════════════ -->
<div class="section">
  <h2 class="section-title"><span class="section-icon">🎯</span> Strategic Recommendations</h2>
  <p class="section-sub">Data-driven actions for category management, pricing optimization, and customer experience improvement</p>

  <div class="rec-grid">
    <div class="rec-card">
      <div class="rec-num">01</div>
      <div class="rec-title">Rationalize Heavy-Discount SKUs</div>
      <div class="rec-body">Products in the 80–100% discount bracket average the lowest ratings (4.02★) and lowest review volume (9,954 avg). These likely represent clearance inventory or low-quality private label. Audit this cohort of 96 products and remove or restructure rather than continuing to promote them at extreme discounts.</div>
      <span class="rec-stat">80–100% disc. bracket: 4.02★ avg vs. 4.21★ for 0–10% disc.</span>
    </div>
    <div class="rec-card">
      <div class="rec-num">02</div>
      <div class="rec-title">Grow the Premium Segment (₹5K+)</div>
      <div class="rec-body">The ₹5K+ price segment delivers the highest average rating (4.17★) with the smallest average discount (33.5%), suggesting these products earn customer satisfaction on merit, not price cuts. Prioritize assortment expansion in this segment — increasing premium SKU share improves catalog quality scores without margin erosion.</div>
      <span class="rec-stat">₹5K+ segment: 4.17★ avg, 33.5% avg discount (206 products)</span>
    </div>
    <div class="rec-card">
      <div class="rec-num">03</div>
      <div class="rec-title">Elevate Home &amp; Kitchen Category</div>
      <div class="rec-body">Home &amp; Kitchen ranks last among the three major categories with a 4.04★ average across 448 products, despite only 40% average discounting (lowest intensity). The lower ratings are not discount-related, pointing to underlying product or listing quality issues. Invest in content quality reviews, stricter supplier ratings thresholds, and sub-category curation for this segment.</div>
      <span class="rec-stat">Home &amp; Kitchen: 4.04★ vs. catalog avg 4.10★ across 448 products</span>
    </div>
    <div class="rec-card">
      <div class="rec-num">04</div>
      <div class="rec-title">Leverage Office Products as a Quality Benchmark</div>
      <div class="rec-body">Office Products achieves the highest average rating (4.31★) with the lowest average discount intensity (12.4%) — a clear signal that this category succeeds through product quality, not promotions. Use Office Products' supplier and content standards as a quality benchmark for other categories, and consider expanding assortment to capitalize on high customer satisfaction.</div>
      <span class="rec-stat">Office Products: 4.31★, only 12.4% avg discount (31 products)</span>
    </div>
    <div class="rec-card">
      <div class="rec-num">05</div>
      <div class="rec-title">Prioritize High-Engagement SKU Quality Control</div>
      <div class="rec-body">The top 10 most-reviewed products (all Electronics, avg 363K+ reviews) set catalog perception for millions of customers. All rate 4.1–4.4★ — healthy but not exceptional. A single quality failure in these SKUs has outsized reputational impact. Implement proactive monitoring and faster listing remediation for products exceeding 100K reviews.</div>
      <span class="rec-stat">Top 10 products avg 380K+ reviews each; median product: 5,179</span>
    </div>
