      legend: {{ display: true, position: 'right', labels: {{ boxWidth: 12, font: {{ size: 11 }}, color: '#6b7a8d' }} }},
      tooltip: {{ callbacks: {{ label: ctx => ` ${{ctx.label}}: ${{ctx.raw}} products` }} }}
