}});

// ─── 3. Category avg rating (horizontal bar) ─────────────────────────────────
new Chart(document.getElementById('catRatingChart'), {{
  type: 'bar',
  data: {{
    labels: catNames,
    datasets: [{{
      data: {cat_ratings},
      backgroundColor: catColors,
